const limit = msg.payload.limit || 1000000;
const chunkSize = 50000;
let current = 0;

const startTime = Date.now();

function isPrime(num) {
    for (let i = 2, s = Math.sqrt(num); i <= s; i++) {
        if (num % i === 0) return false;
    }
    return num > 1;
}

function processChunk() {
    const end = Math.min(current + chunkSize, limit);

    for (; current <= end; current++) {
        isPrime(current);
    }

    if (current < limit) {
        // Use setTimeout instead of setImmediate
        // 0ms delay tells Node-RED: "Finish other tasks, then come back to this."
        setTimeout(() => {
            processChunk();
        }, 0);
    } else {
        // We use node.send because the function has already "returned"
        const duration = Date.now() - startTime;
        node.send({
            payload: {
                status: "Completed",
                execution_time_ms: duration,
                limit: limit
            }
        });
        node.done();
    }
}

// Start the process
processChunk();

// Return null to tell Node-RED not to send a message yet
return null;

